module pll(clk_in, ctrl, clk_out);  
    input clk_in;  
    input [2:0] ctrl; // Control input to determine division factor  
    output reg clk_out;  
    reg [2:0] count;  

    always @(posedge clk_in) begin  
        if (count < ctrl)  
            count <= count + 1;  
        else begin  
            clk_out <= ~clk_out;  
            count <= 3'b000;  
        end  
    end  

    initial begin  
        count = 3'b000;  
        clk_out = 1'b0;  
    end  
endmodule

