module clock_divider (
    input wire clk_in,
    input wire rst,
    input wire [3:0] div_factor,
    output reg clk_out
);
    reg [3:0] counter;

    always @(posedge clk_in or posedge rst) begin
        if (rst) begin
            counter <= 0;
            clk_out <= 0;
        end else begin
            if (counter == div_factor - 1) begin
                clk_out <= ~clk_out;
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

