module EchoCancellation #(parameter BUFFER_SIZE = 4)(
    input clk,
    input rst,
    input [15:0] input_signal,
    output reg [15:0] output_signal
);
    reg [15:0] buffer [0:BUFFER_SIZE-1];
    reg [1:0] write_ptr;
    reg [1:0] read_ptr;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            write_ptr <= 0;
            read_ptr <= 0;
            output_signal <= 0;
        end else begin
            output_signal <= input_signal - buffer[read_ptr];
            buffer[write_ptr] <= input_signal;
            write_ptr <= (write_ptr + 1) % BUFFER_SIZE;
            read_ptr <= (read_ptr + 1) % BUFFER_SIZE;
        end
    end
endmodule

