module Adaptive_LMS_Filter (
    input clk,
    input reset,
    input [15:0] x,         // input sample
    input [15:0] d,         // desired output
    output reg [15:0] y,    // actual output
    output reg [15:0] w0,    // coefficient 0
    output reg [15:0] w1,    // coefficient 1
    output reg [15:0] w2     // coefficient 2
);
    reg [15:0] x_delayed[0:2]; // delay line for inputs
    reg [15:0] error;          // error signal
    parameter mu = 16'h0001;   // step size for adaptation

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            w0 <= 16'h0000;
            w1 <= 16'h0000;
            w2 <= 16'h0000;
            y <= 16'h0000;
            x_delayed[0] <= 16'h0000;
            x_delayed[1] <= 16'h0000;
            x_delayed[2] <= 16'h0000;
        end else begin
            // Shift the delay line
            x_delayed[2] <= x_delayed[1];
            x_delayed[1] <= x_delayed[0];
            x_delayed[0] <= x;

            // Calculate actual output
            y <= (w0 * x_delayed[0]) + (w1 * x_delayed[1]) + (w2 * x_delayed[2]);

            // Compute error
            error <= d - y;

            // Update weights
            w0 <= w0 + (mu * error * x_delayed[0]);
            w1 <= w1 + (mu * error * x_delayed[1]);
            w2 <= w2 + (mu * error * x_delayed[2]);
        end
    end
endmodule

