module chebyshev_filter (  
    input clk,  
    input reset,  
    input [7:0] x_in,  
    output reg [7:0] y_out  
);  
    reg [7:0] x_reg [0:2]; // Store input samples  
    reg [7:0] y_reg [0:1]; // Store output samples  
    reg [1:0] state;  
    parameter IDLE = 2'b00,  
              CALC = 2'b01,  
              OUTPUT = 2'b10;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            y_out <= 8'b0;  
            x_reg[0] <= 8'b0;  
            x_reg[1] <= 8'b0;  
            x_reg[2] <= 8'b0;  
            y_reg[0] <= 8'b0;  
            y_reg[1] <= 8'b0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    x_reg[0] <= x_in; // Store the current input  
                    x_reg[1] <= x_reg[0]; // Shift old values  
                    x_reg[2] <= x_reg[1]; // Shift old values  
                    state <= CALC;  
                end  
                CALC: begin  
                    // Chebyshev filter calculation (example coefficients)  
                    y_reg[0] <= (x_reg[0] + 2 * x_reg[1] + x_reg[2]) >> 1;  
                    y_reg[1] <= y_reg[0]; // Shift output  
                    state <= OUTPUT;  
                end  
                OUTPUT: begin  
                    y_out <= y_reg[1];  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

