module fractional_n_pll (
    input wire clk_in,
    input wire reset,
    input wire [7:0] fractional_value,
    output reg clk_out
);
    reg [7:0] counter;
    reg [7:0] divider;

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            counter <= 0;
            clk_out <= 0;
            divider <= 1;
        end else begin
            if (counter >= divider) begin
                clk_out <= ~clk_out;
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end
    end

    always @(posedge clk_in) begin
        divider <= fractional_value + 1; // Adding 1 to avoid division by zero
    end
endmodule

