module watchdog_timer #(parameter THRESHOLD = 10) (
    input wire clk,
    input wire reset,
    input wire enable,
    output reg timeout
);
    reg [3:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            timeout <= 0;
        end else if (enable) begin
            if (count < THRESHOLD) begin
                count <= count + 1;
                timeout <= 0;
            end else begin
                timeout <= 1;
            end
        end
    end
endmodule

