module md5_simple(
    input clk,
    input rst,
    input [511:0] data_in,
    input start,
    output reg [127:0] hash_out,
    output reg done
);

    reg [127:0] a, b, c, d;
    reg [3:0] state; // state machine for processing
    reg [4:0] round;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= 0;
            a <= 32'h67452301;
            b <= 32'hEFCDAB89;
            c <= 32'h98BADCFE;
            d <= 32'h10325476;
            hash_out <= 0;
            done <= 0;
            round <= 0;
        end else if (start) begin
            case (state)
                0: begin // Initialization
                    state <= 1;
                end
                1: begin // Process input data
                    // Simplified processing, just an example
                    a <= a + data_in[127:0] + (b & c | ~b & d);
                    b <= b + data_in[255:128] + (a & d | c & ~a);
                    c <= c + data_in[383:256] + (b & a | d & ~b);
                    d <= d + data_in[511:384] + (c & b | a & ~c);
                    round <= round + 1;
                    if (round == 4) begin
                        state <= 2; // Proceed to final state
                    end
                end
                2: begin // Final output
                    hash_out <= {a, b, c, d};
                    done <= 1;
                    state <= 0; // Reset state
                end
            endcase
        end
    end
endmodule

