module instruction_pipeline (
    input clk,
    input rst,
    input [31:0] instruction_in,
    output reg [31:0] instruction_out
);

    reg [31:0] IF_ID_instruction;  // Instruction fetched
    reg [31:0] ID_EX_instruction;  // Instruction decoded
    reg [31:0] EX_MEM_instruction;  // Instruction executed
    reg [31:0] MEM_WB_instruction;  // Instruction to be written back

    // Fetch Stage
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            IF_ID_instruction <= 32'b0;
        end else begin
            IF_ID_instruction <= instruction_in;
        end
    end

    // Decode Stage
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            ID_EX_instruction <= 32'b0;
        end else begin
            ID_EX_instruction <= IF_ID_instruction;
        end
    end

    // Execute Stage
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            EX_MEM_instruction <= 32'b0;
        end else begin
            EX_MEM_instruction <= ID_EX_instruction;
        end
    end

    // Memory Stage
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            MEM_WB_instruction <= 32'b0;
        end else begin
            MEM_WB_instruction <= EX_MEM_instruction;
        end
    end

    // Write Back Stage
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            instruction_out <= 32'b0;
        end else begin
            instruction_out <= MEM_WB_instruction;
        end
    end

endmodule

