module turbo_encoder(
    input clk,
    input rst,
    input [3:0] data_in,
    output reg [5:0] encoded_out
);

reg [3:0] interleaved_data;
reg [5:0] conv_encoder1_out;
reg [5:0] conv_encoder2_out;

// Simple convolutional encoder
function [5:0] conv_encoder;
    input [3:0] data;
    begin
        conv_encoder[0] = data[0] ^ data[1];
        conv_encoder[1] = data[1] ^ data[2];
        conv_encoder[2] = data[2] ^ data[3];
        conv_encoder[3] = data[0] ^ data[2];
        conv_encoder[4] = data[1] ^ data[3];
        conv_encoder[5] = data[0] ^ data[1] ^ data[2] ^ data[3];
    end
endfunction

// Interleave the data
always @(data_in) begin
    interleaved_data[0] = data_in[0];
    interleaved_data[1] = data_in[2];
    interleaved_data[2] = data_in[1];
    interleaved_data[3] = data_in[3];
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        encoded_out <= 6'b0;
    end else begin
        conv_encoder1_out = conv_encoder(data_in);
        conv_encoder2_out = conv_encoder(interleaved_data);
        encoded_out <= {conv_encoder1_out[5:0], conv_encoder2_out[5:0]};
    end
end

endmodule

module stop_and_wait (
    input clk,
    input reset,
    input send_packet,
    input ack_received,
    output reg packet_sent,
    output reg retransmit,
    output reg [1:0] state
);

    parameter IDLE = 2'b00, WAIT_ACK = 2'b01, ACK_RECEIVED = 2'b10, TIMEOUT = 2'b11;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            packet_sent <= 0;
            retransmit <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (send_packet) begin
                        packet_sent <= 1;
                        retransmit <= 0;
                        state <= WAIT_ACK;
                    end
                end
                WAIT_ACK: begin
                    if (ack_received) begin
                        packet_sent <= 0;
                        state <= ACK_RECEIVED;
                    end else begin
                        retransmit <= 1; // No ACK received, retransmit the packet
                    end
                end
                ACK_RECEIVED: begin
                    packet_sent <= 0;
                    retransmit <= 0;
                    state <= IDLE;
                end
                TIMEOUT: begin
                    packet_sent <= 0; 
                    retransmit <= 1; // Timeout occurs, retransmit the packet
                    state <= IDLE; 
                end
            endcase
        end
    end
endmodule

module flash_memory_cell (  
    input wire clk,  
    input wire rst,  
    input wire we,  
    input wire re,  
    input wire [7:0] data_in,  
    output reg [7:0] data_out  
);  

    reg [7:0] memory;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            memory <= 8'b0;  
            data_out <= 8'b0;  
        end else if (we) begin  
            memory <= data_in;  
        end else if (re) begin  
            data_out <= memory;  
        end  
    end  
endmodule

module timer_16bit (  
    input wire clk,  
    input wire reset,  
    output reg [15:0] count  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset)  
            count <= 16'b0;  
        else  
            count <= count + 1;  
    end  
endmodule

