module audio_sample_rate_converter (
    input wire clk,              // System clock
    input wire reset,            // Reset signal
    input wire [15:0] audio_in,  // 16-bit audio input
    input wire audio_in_valid,    // Valid signal for audio input
    output reg [15:0] audio_out,  // 16-bit audio output
    output reg audio_out_valid     // Valid signal for audio output
);
    reg [3:0] counter;              // Counter for sample rate conversion
    reg [15:0] fifo [0:3];          // FIFO buffer for 4 samples
    reg [1:0] fifo_head;            // FIFO head pointer
    reg [1:0] fifo_tail;            // FIFO tail pointer
    reg [1:0] sample_count;         // Sample counter for input

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            fifo_head <= 0;
            fifo_tail <= 0;
            sample_count <= 0;
            audio_out_valid <= 0;
        end else begin
            // Store incoming audio samples in FIFO
            if (audio_in_valid && sample_count < 4) begin
                fifo[fifo_head] <= audio_in;
                fifo_head <= fifo_head + 1;
                sample_count <= sample_count + 1;
            end

            // Output audio samples at 48 kHz
            if (counter == 1) begin
                if (fifo_tail < fifo_head) begin
                    audio_out <= fifo[fifo_tail];
                    audio_out_valid <= 1;
                    fifo_tail <= fifo_tail + 1;
                end else begin
                    audio_out_valid <= 0; // No valid output
                end
            end

            // Increment sample rate conversion counter
            counter <= counter + 1;
            if (counter == 4) begin
                counter <= 0;
            end
        end
    end
endmodule

