module pcie_transaction_decoder (
    input [2:0] txn_type,
    input [4:0] address,
    output reg valid,
    output reg [1:0] response
);

always @(*) begin
    case (txn_type)
        3'b000: begin // READ
            valid = 1'b1;
            response = 2'b00;
        end
        3'b001: begin // WRITE
            valid = 1'b1;
            response = 2'b01;
        end
        3'b010: begin // CONFIG
            valid = 1'b1;
            response = 2'b10;
        end
        default: begin // Invalid transaction
            valid = 1'b0;
            response = 2'b11;
        end
    endcase
end

endmodule

module rising_edge_detector(  
    input clk,  
    input signal_in,  
    output reg edge_detected  
);  
    reg signal_in_prev;  

    always @(posedge clk) begin  
        edge_detected <= (signal_in && !signal_in_prev);  
        signal_in_prev <= signal_in;  
    end  
endmodule

module arq_system (
    input clk,
    input rst,
    input [4:0] data_in,
    input data_valid,
    output reg [4:0] received_data,
    output reg resend,
    output reg parity_error
);
    reg [4:0] sent_data;
    reg parity_bit;

    // Function to calculate parity
    function parity;
        input [4:0] data;
        integer i;
        begin
            parity = 0;
            for (i = 0; i < 5; i = i + 1) begin
                parity = parity ^ data[i];
            end
        end
    endfunction

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sent_data <= 0;
            received_data <= 0;
            resend <= 0;
            parity_error <= 0;
        end else if (data_valid) begin
            sent_data <= data_in;
            parity_bit <= parity(data_in);
            // Simulating transmission and reception with potential error
            if (sent_data[0] ^ parity_bit) begin
                parity_error <= 1; // Simulate an error
                resend <= 1; // Request resend
            end else begin
                received_data <= sent_data; // Correct data received
                resend <= 0;
                parity_error <= 0;
            end
        end
    end
endmodule

