module chacha20_quarter_round (
    input wire clk,
    input wire rst,
    input wire [31:0] a,
    input wire [31:0] b,
    input wire [31:0] c,
    input wire [31:0] d,
    output reg [31:0] out_a,
    output reg [31:0] out_b,
    output reg [31:0] out_c,
    output reg [31:0] out_d
);

    reg [31:0] temp_a, temp_b, temp_c, temp_d;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            out_a <= 0;
            out_b <= 0;
            out_c <= 0;
            out_d <= 0;
        end else begin
            temp_a <= a + b;
            temp_d <= d ^ temp_a;
            temp_d <= {temp_d[22:0], temp_d[31:22]}; // Rotate left by 13
            temp_c <= c + temp_d;
            temp_b <= b ^ temp_c;
            temp_b <= {temp_b[19:0], temp_b[31:20]}; // Rotate left by 8
            temp_a <= temp_a + temp_b;
            temp_d <= d ^ temp_a;
            temp_d <= {temp_d[13:0], temp_d[31:13]}; // Rotate left by 7
            temp_c <= temp_c + temp_d;
            temp_b <= temp_b ^ temp_c;
            temp_b <= {temp_b[18:0], temp_b[31:18]}; // Rotate left by 16

            // Update outputs
            out_a <= temp_a;
            out_b <= temp_b;
            out_c <= temp_c;
            out_d <= temp_d;
        end
    end
endmodule

module nvme_controller (
    input wire clk,
    input wire reset,
    input wire command_received,
    output reg [1:0] state, // 00 = IDLE, 01 = PROCESSING, 10 = DONE
    output reg done_signal
);

    // State encoding
    localparam IDLE = 2'b00;
    localparam PROCESSING = 2'b01;
    localparam DONE = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            done_signal <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (command_received) begin
                        state <= PROCESSING;
                        done_signal <= 0;
                    end
                end
                PROCESSING: begin
                    // Simulate processing time
                    state <= DONE; // Go directly to DONE for simplicity
                end
                DONE: begin
                    done_signal <= 1; // Signal that processing is done
                    state <= IDLE; // Go back to IDLE for next command
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

module reset_controller(  
    input wire clk,  
    input wire reset,  
    input wire [3:0] duration,  
    output reg rst_out  
);  
    reg [3:0] counter;  
    reg active;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            rst_out <= 1;  
            counter <= duration;  
            active <= 1;  
        end else if (active) begin  
            if (counter > 0) begin  
                counter <= counter - 1;  
            end else begin  
                rst_out <= 0;  
                active <= 0;  
            end  
        end  
    end  
endmodule

