module divider_4bit (
    input wire clk,
    input wire rst,
    input wire [3:0] dividend,
    input wire [3:0] divisor,
    output reg [3:0] quotient,
    output reg [3:0] remainder,
    output reg valid
);
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            quotient <= 4'b0000;
            remainder <= 4'b0000;
            valid <= 0;
        end else begin
            if (divisor == 4'b0000) begin
                quotient <= 4'b0000;
                remainder <= dividend;
            end else begin
                quotient <= dividend / divisor;
                remainder <= dividend % divisor;
            end
            valid <= 1;
        end
    end
endmodule

module iir_filter (
    input clk,
    input reset,
    input signed [15:0] x,      // Current input
    input signed [15:0] a,      // Feedback input
    output reg signed [15:0] y,  // Current output
    output reg signed [15:0] b   // Feedback output
);
    parameter signed [15:0] b0 = 16'd1;
    parameter signed [15:0] b1 = 16'd2;
    parameter signed [15:0] a1 = 16'd1;
    parameter signed [15:0] a2 = 16'd1;

    reg signed [15:0] y_prev1, y_prev2;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            y <= 16'd0;
            b <= 16'd0;
            y_prev1 <= 16'd0;
            y_prev2 <= 16'd0;
        end else begin
            y <= (b0 * x) + (b1 * y_prev1) - (a1 * a) - (a2 * y_prev2);
            b <= a;  // Update feedback output
            y_prev2 <= y_prev1;  // Shift previous outputs
            y_prev1 <= y;
        end
    end
endmodule

