module pipelined_processor (  
    input clk,  
    input reset,  
    input [4:0] instruction,  
    output reg [4:0] result  
);  

    reg [4:0] IF_ID_instruction;  
    reg [4:0] ID_EX_instruction;  
    reg [4:0] EX_MEM_instruction;  
    reg [4:0] MEM_WB_instruction;  
    reg [4:0] ALU_result;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            IF_ID_instruction <= 5'b00000;  
            ID_EX_instruction <= 5'b00000;  
            EX_MEM_instruction <= 5'b00000;  
            MEM_WB_instruction <= 5'b00000;  
            result <= 5'b00000;  
        end else begin  
            IF_ID_instruction <= instruction;  
            ID_EX_instruction <= IF_ID_instruction;  
            case (ID_EX_instruction[4:3])  
                2'b00: ALU_result <= ID_EX_instruction[2:0] + ID_EX_instruction[2:0]; // ADD  
                2'b01: ALU_result <= ID_EX_instruction[2:0] - ID_EX_instruction[2:0]; // SUB  
                2'b10: ALU_result <= ID_EX_instruction[2:0] & ID_EX_instruction[2:0]; // AND  
                2'b11: ALU_result <= ID_EX_instruction[2:0] | ID_EX_instruction[2:0]; // OR  
                default: ALU_result <= 5'b00000;  
            endcase  
            EX_MEM_instruction <= ALU_result;  
            result <= EX_MEM_instruction;  
        end  
    end  
endmodule

